from django.db import migrations


def assign_acts_to_cabinets(apps, schema_editor):
    """The act catalogue used to be global. Hand the existing acts to the first
    cabinet and give every other cabinet its own copy, so no doctor loses acts
    once views filter MedicalAct by cabinet. Historical ConsultationAct /
    InvoiceItem rows keep pointing at the original act (their price is copied)."""
    Cabinet = apps.get_model("accounts", "Cabinet")
    MedicalAct = apps.get_model("billing", "MedicalAct")

    orphan_acts = list(MedicalAct.objects.filter(cabinet__isnull=True))
    cabinets = list(Cabinet.objects.order_by("pk"))
    if not orphan_acts or not cabinets:
        return

    first, others = cabinets[0], cabinets[1:]
    MedicalAct.objects.filter(pk__in=[act.pk for act in orphan_acts]).update(cabinet=first)
    for cabinet in others:
        MedicalAct.objects.bulk_create(
            MedicalAct(
                cabinet=cabinet,
                code=act.code,
                name=act.name,
                price=act.price,
                is_active=act.is_active,
                is_quick_exam=act.is_quick_exam,
            )
            for act in orphan_acts
        )


